    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BuildReport {
        return
            try BuildReport(
                total: FfiConverterUInt64.read(from: &buf), 
                skipped: FfiConverterUInt64.read(from: &buf), 
                diff: FfiConverterTypeNodeDiff.read(from: &buf), 
                tookMillis: FfiConverterUInt64.read(from: &buf)
        )
    }

    public static func write(_ value: BuildReport, into buf: inout [UInt8]) {
        FfiConverterUInt64.write(value.total, into: &buf)
        FfiConverterUInt64.write(value.skipped, into: &buf)
        FfiConverterTypeNodeDiff.write(value.diff, into: &buf)
        FfiConverterUInt64.write(value.tookMillis, into: &buf)
    }
}


