/**
 * 流式建库：push 时立即压成 24 B 记录 + 名称字节，不保留 NodeInput。
 * 1310 万节点峰值内存 ≈ 记录 315 MB + 名称 ~330 MB + 去重临时 210 MB（原实现 2.7 GB 会被 OOM 杀掉）。
 * 建库阶段（进度回调用）。
 */

public enum BuildPhase {
    
    /**
     * 解析订阅 / 生成节点；total = 0 表示总数未知
     */
    case parse
    /**
     * 建倒排索引
     */
    case index
    /**
     * 写文件
     */
    case write
}


